dcl-proc ConfirmarOrdemSQL;
  dcl-pi *n ind;
    pViagem packed(9:0) const;
    pTransp packed(5:0) const;
  end-pi;

  monitor;
    exec sql update FCARGAD set FDFLAG = 'S' where FDVIAT = :pViagem and FDCTRANS = :pTransp;
    exec sql update FCARGAH set FHFLAG = 'S' where FHVIAT = :pViagem and FHCTRANS = :pTransp;
    exec sql commit;
    return *on;
  on-error;
    exec sql rollback;
    return *off;
  endmon;
end-proc;

output:
@Service
public class TransporteOrderService {

    @Autowired
    private CargaHeaderRepository cargaHeaderRepository;
    @Autowired
    private CargaDetailRepository cargaDetailRepository;

    @Transactional
    public boolean confirmarOrdem(Long numeroViagem, Integer codigoTransportadora) {
        try {
            cargaDetailRepository.atualizarStatus(numeroViagem, codigoTransportadora, "S");
            cargaHeaderRepository.atualizarStatus(numeroViagem, codigoTransportadora, "S");
            return true;
        } catch (DataAccessException e) {
            // O Rollback e gerenciado automaticamente pelo Spring @Transactional
            return false;
        }
    }
}

