public record ClienteCreditoDTO(Long id, String situacao, BigDecimal limiteCredito) {}

@Service
public class AnáliseCreditoService {

    public void analisarCredito(ClienteCreditoDTO cliente, BigDecimal valorPedido) {
        if ("I".equalsIgnoreCase(cliente.situacao())) {
            throw new BusinessException("Cliente bloqueado/inativo");
        }
        if (valorPedido.compareTo(cliente.limiteCredito()) > 0) {
            throw new BusinessException("Valor do pedido excede limite de credito");
        }
    }
}
